// 固定源码数据：gzip解压后逐项SHA256核验，只读解析，不执行fixture脚本。
const edgePayload = "";
const edgeDigests = {"packages/quality/vitest.config.ts": "a9163321496b5f40a73bfdd3efab18478f3d2da16e3906f413b7f7fb119f4001", "packages/quality/__tests__/goldset-eval-cli.test.js": "8515a4c95b0d8e55b9ca967a66948ee3de8470ad4da0655d095b5a6a4548eecd", "tests/regression/version-gate-silent/check-brain-version-bump.test.js": "d06ad5482e7200ff5101cb30b0859b3539adf460cf14204a33b2c3240c56c53e", ".github/workflows/implementation-impact.yml": "a6f22b00e6daf24e2925bcac7a8e13cc2dcdc54744eed476f922cf57ff6c5ff8"};
const edgeBytes = gunzipSync(Buffer.from(edgePayload, 'base64'), {maxOutputLength: 128 * 1024});
if (createHash('sha256').update(edgeBytes).digest('hex') !== '07e2fc5254a3fefc7943d72a1d98eadb113da29b7719a22bc46eea709971a5a6') throw Error('edge fixture payload mismatch');
const edgeInputs = JSON.parse(edgeBytes);
if (JSON.stringify(Object.keys(edgeInputs).sort()) !== JSON.stringify(Object.keys(edgeDigests).sort())) throw Error('edge fixture path mismatch');
for (const [path,text] of Object.entries(edgeInputs)) if (createHash('sha256').update(text).digest('hex') !== edgeDigests[path]) throw Error('edge fixture blob mismatch');
const edgePaths = [...new Set([...paths, ...apiInputs, ...Object.keys(apiTuple), ...Object.keys(edgeInputs)])];
const graph = (overrides = {}, missing = []) => collectWorkspaceInputEdges({revision, parse,
  paths: edgePaths.filter(p => !missing.includes(p)), readSource: reader({...apiTuple, ...edgeInputs, ...overrides})});
const qualityConfig = 'packages/quality/vitest.config.ts', qualityTest = 'packages/quality/__tests__/goldset-eval-cli.test.js';
const versionTest = 'tests/regression/version-gate-silent/check-brain-version-bump.test.js', impact = '.github/workflows/implementation-impact.yml';
const nodeRoots = ['implementation-main-snapshot', 'workspace-ci-source-bundle', 'implementation-skill-source', 'device-patrol-governance'].map(n => `scripts/ci/__tests__/${n}.test.mjs`);
const mutateImpact = change => {const doc = yaml.load(edgeInputs[impact]); change(doc.jobs.gate); return yaml.dump(doc);};
describe('新basic真实选择及来源机制单元入口闭包', () => {
  it('API四测试、真实Quality/Brain诊断和无条件四Node入口有准确来源边', async () => {
    const edges = await graph();
    for (const [src_path,dst_path] of [
      ...['BusinessInputs','CapabilitySystem','EvidenceView','InvocationPanel'].map(n => [config, `apps/api/features/planning/pages/capability-system/${n}.test.tsx`]),
      [qualityConfig,qualityTest], [qualityTest,'packages/quality/skill-distillation/scripts/goldset-eval.mjs'],
      ['packages/brain/vitest.config.js',versionTest], [versionTest,'scripts/ci/check-brain-version-bump.sh'], ...nodeRoots.map(p => [impact,p]),
    ]) expect(edges).toContainEqual(expect.objectContaining({src_path,dst_path,edge_type:'import'}));
  });
  for (const [name, overrides] of [
    ['API未知选择器', {[config]: apiTuple[config].replace('include: [', 'include: [process.env.TESTS,')}],
    ['API排除实际测试', {[config]: apiTuple[config].replace("'node_modules'", "'features/**', 'node_modules'")}],
    ['Quality排除实际测试', {[qualityConfig]: edgeInputs[qualityConfig].replace('exclude: [', "exclude: ['__tests__/**',")}],
    ['Quality未知root', {[qualityConfig]: edgeInputs[qualityConfig].replace('test: {', "test: {root: process.env.ROOT,")}],
    ['goldset替身', {[qualityTest]: edgeInputs[qualityTest].replace('scripts/goldset-eval.mjs', 'scripts/fake.mjs')}],
    ['goldset死分支', {[qualityTest]: edgeInputs[qualityTest].replace('const child = spawn(', 'if (false) { const child = spawn(') + '}'}],
    ['版本假echo', {[versionTest]: edgeInputs[versionTest].replace("spawnSync('bash', [SCRIPT]", "spawnSync('echo', [SCRIPT]")}],
    ['版本死分支', {[versionTest]: edgeInputs[versionTest].replace('const result = spawnSync', 'if (false) return; const result = spawnSync')}],
  ]) it(`${name}拒绝`, async () => {await expect(graph(overrides)).rejects.toThrow(/workspace/i);});
  for (const [name,change] of [
    ['缺source checkout', j => {j.steps = j.steps.filter(s => s.with?.path !== 'source');}],
    ['checkout条件跳过', j => {j.steps.find(s => s.with?.path === 'source').if = 'false';}],
    ['Node入口替身脚本', j => {const s=j.steps.find(s => s.name === '来源机制完整单元回归');s.run=s.run.replace('implementation-main-snapshot.test.mjs','fake.test.mjs');}],
    ['Node入口覆盖环境', j => {j.steps.find(s => s.name === '来源机制完整单元回归').env = {NODE_OPTIONS:'--import ./fake.mjs'};}],
    ['checkout错ref', j => {j.steps.find(s => s.with?.path === 'source').with.ref = 'main';}],
    ['Node入口错cwd', j => {j.steps.find(s => s.name === '来源机制完整单元回归')['working-directory'] = 'tooling';}],
    ['Node入口假echo', j => {j.steps.find(s => s.name === '来源机制完整单元回归').run = 'echo node --test';}],
    ['Node入口条件跳过', j => {j.steps.find(s => s.name === '来源机制完整单元回归').if = 'false';}],
    ['Node入口死分支', j => {const s=j.steps.find(s => s.name === '来源机制完整单元回归'); s.run='if false; then '+s.run+'; fi';}],
  ]) it(`${name}拒绝`, async () => {await expect(graph({[impact]:mutateImpact(change)})).rejects.toThrow(/workspace/i);});
  for (const [name,trigger] of [['仅手动',{workflow_dispatch:{}}],['PR分支过滤',{pull_request:{branches:['other']},push:{branches:['main']}}],['PR路径过滤',{pull_request:{branches:['main'],paths:['docs/**']},push:{branches:['main']}}]])
    it(`${name}不能证明自动Node入口`,async()=>{const doc=yaml.load(edgeInputs[impact]);doc.on=trigger;await expect(graph({[impact]:yaml.dump(doc)})).rejects.toThrow(/workspace/i);});
  for (const [name,edit] of [
    ['缺runs-on',d=>{delete d.jobs.gate['runs-on'];}],['依赖自环',d=>{d.jobs.gate.needs=['gate'];}],
    ['空matrix',d=>{d.jobs.gate.strategy={matrix:{include:[]}};}],['缺依赖任务',d=>{delete d.jobs['snapshot-main'];}],
    ['祖先依赖环',d=>{d.jobs['snapshot-main'].needs=['gate'];}],['祖先缺runner',d=>{delete d.jobs['snapshot-main']['runs-on'];}],
    ['未知workflow控制字段',d=>{d['unknown-control']=true;}],
  ]) it(`${name}不能证明可达Node前缀`,async()=>{const doc=yaml.load(edgeInputs[impact]);edit(doc);await expect(graph({[impact]:yaml.dump(doc)})).rejects.toThrow(/workspace/i);});
  it.each([qualityTest,versionTest,...nodeRoots])('缺少实际输入%s拒绝', async path => {await expect(graph({},[path])).rejects.toThrow(/workspace/i);});
  it('新controls5dca与精确Cecelia-only条件证明native Node入口，旧79封套仍保持',async()=>{
   const text=readFileSync(join(root,'.github/workflows/implementation-impact.yml'),'utf8');
   expect(createHash('sha256').update(text).digest('hex')).toBe('17d29709a4990f9a0b4c2bbc63ad2dbcb7ce4f2b635a5d1fb416e8239d30f3b6');
   const edges=await graph({[impact]:text});for(const path of nodeRoots)expect(edges).toContainEqual(expect.objectContaining({src_path:impact,dst_path:path,detail:expect.objectContaining({selector_kind:'native_repository_source_node_test_entry'})}));
   expect((await graph()).filter(e=>nodeRoots.includes(e.dst_path))).toHaveLength(4);
  });
  for(const [name,edit]of[
   ['去native条件',d=>{delete d.jobs.gate.steps.find(s=>s.name==='来源机制完整单元回归').if;}],
   ['native恒真',d=>{d.jobs.gate.steps.find(s=>s.name==='来源机制完整单元回归').if='true';}],
   ['放宽sourceRepo',d=>{d.jobs.gate.steps.find(s=>s.name==='来源机制完整单元回归').if="github.repository == 'perfectuser21/cecelia'";}],
   ['typed header混旧push',d=>{d.on.push={branches:['main']};}],
   ['未来缺祖先',d=>{delete d.jobs['snapshot-main'];}],
  ])it(`新native profile拒绝${name}`,async()=>{const d=yaml.load(readFileSync(join(root,'.github/workflows/implementation-impact.yml'),'utf8'));edit(d);await expect(graph({[impact]:yaml.dump(d)})).rejects.toThrow(/workspace/i);});
});

